import type { Example } from "../example.ts"
import { html, type TemplateResult } from "lit-html"

export type AvatarSize = "sm" | "md" | "lg"

export type AvatarProps = { initials: string; name: string; size: AvatarSize; square?: boolean; class?: string }

export type AvatarFill = "coloured" | "outline" | "photo"

const sizes: Record<AvatarSize, string> = {
  sm: "w-avatar.sm h-avatar.sm text-xs",
  md: "w-avatar.md h-avatar.md text-xs",
  lg: "w-avatar.lg h-avatar.lg text-xl",
}

const initials = "inline-flex items-center justify-center font-semibold"

// coloured: the app sets the person's colour as the background; the initials are white on it in both themes (no colour token is white in dark).
const fills: Record<AvatarFill, string> = {
  coloured: `${initials} text-white`,
  outline: `${initials} bg-subtle text-muted ring-1 ring-inset ring-line`,
  photo: "object-cover",
}

/** Apps put these classes on their own avatar, with avatarSizeClass(); "photo" goes on an <img>. How it sits in a row (shrink-0) is app code. */
export function avatarClass(look: { fill: AvatarFill; square?: boolean }): string {
  return `${look.square === true ? "rounded-md" : "rounded-full"} ${fills[look.fill]}`
}

/** The avatar's size and initials size. */
export function avatarSizeClass(size: AvatarSize): string {
  return sizes[size]
}

// Primer shows a photo; there is none here, so the initials stand in and the name is the image's label.
export function avatar(props: AvatarProps): TemplateResult {
  const classes = [avatarSizeClass(props.size), avatarClass({ fill: "outline", square: props.square })]
  if (props.class !== undefined) classes.push(props.class)
  return html`<span role="img" aria-label=${props.name} class=${classes.join(" ")}><span aria-hidden="true">${props.initials}</span></span>`
}

export const examples: Example[] = [
  { label: "sm", render: () => avatar({ initials: "NK", name: "Nils K", size: "sm" }) },
  { label: "md", render: () => avatar({ initials: "NK", name: "Nils K", size: "md" }) },
  { label: "lg", render: () => avatar({ initials: "NK", name: "Nils K", size: "lg" }) },
  { label: "square", render: () => avatar({ initials: "NK", name: "Nils K", size: "md", square: true }) },
]
